import{_ as t,o,c as a,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"ADR-002 — 5-Engine Polyglot Persistence Split","description":"","frontmatter":{},"headers":[],"relativePath":"adr/adr-002-database-split.md","filePath":"adr/adr-002-database-split.md"}'),c={name:"adr/adr-002-database-split.md"};function s(i,e,r,n,l,g){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="adr-002-—-5-engine-polyglot-persistence-split" tabindex="-1">ADR-002 — 5-Engine Polyglot Persistence Split <a class="header-anchor" href="#adr-002-—-5-engine-polyglot-persistence-split" aria-label="Permalink to &quot;ADR-002 — 5-Engine Polyglot Persistence Split&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./README.html">← ADR Index</a> · <a href="./../database/README.html">Database Hub</a> · <a href="/brandhub-infrastructure/view.html?file=architecture/db-ownership-diagram.html">DB Ownership Diagram</a></p><ul><li><strong>Status:</strong> Accepted</li><li><strong>Owners:</strong> Core Backend &amp; AI Architecture Leads</li><li><strong>Related Docs:</strong> <a href="./../database/schema/database-strategy.html">Database Strategy V2</a> · <a href="./../database/schema/erd-entity-descriptions.html">ERD Entity Descriptions</a> · <a href="./../database/redis-cache/database-access-rules.html">Database Access Rules</a></li></ul><hr><h2 id="_1-context-problem-statement" tabindex="-1">1. Context &amp; Problem Statement <a class="header-anchor" href="#_1-context-problem-statement" aria-label="Permalink to &quot;1. Context &amp; Problem Statement&quot;">​</a></h2><p>BrandHub workloads exhibit five fundamentally different data shapes, consistency guarantees, and query access patterns:</p><ol><li><strong>Strict ACID Financial, Identity &amp; Organizational Invariants</strong>: Two-tier tenant hierarchy (<code>Agency</code> with immutable <code>agencies.owner_id</code> → <code>Workspace</code> with per-workspace <code>Manager</code>, <code>Creator</code>, <code>Client</code>), dual-party Media Package sign-off (<code>approved_by_agency_at</code> + <code>approved_by_client_at</code>), <strong>SePay (VietQR)</strong> upgrade-only subscription orders, and double-entry AI credit &amp; S3 storage ledgers cannot tolerate eventual consistency or lost updates.</li><li><strong>Polymorphic, High-Write Content &amp; Collaboration Documents</strong>: <code>Task</code> deliverables (<code>POST</code>, <code>SURVEY</code>, <code>SHORT_VIDEO</code>, <code>EVENT_PLAN</code>, <code>PRESS_RECOMMENDATION</code>, <code>KOL_BOOKING</code>, <code>WORKSHOP</code>, <code>EMAIL_NEWSLETTER</code>), append-only multi-round approvals, Yjs/rich-text snapshots, workspace chat threads, and Video Space timelines evolve rapidly with deeply nested payloads.</li><li><strong>Sub-Millisecond Ephemeral Coordination</strong>: JWT <code>jti</code> revocation checks on every HTTP call, gateway sliding-window rate counters, OAuth CSRF states, and distributed publish locks.</li><li><strong>Dense Semantic Vector Search</strong>: Tenant-isolated <code>384d</code> chunk retrieval over uploaded PDF/DOCX/URL Brand Guidelines (<code>FR 3.7.3</code>–<code>3.7.5</code>).</li><li><strong>Multi-Hop Social Entity Traversal</strong>: Personalized PageRank, entity co-occurrence, and source-post provenance across crawled Vietnamese social trends (<code>FR 3.7.1</code>–<code>3.7.2</code>, <code>FR 3.7.6</code>).</li></ol><hr><h2 id="_2-evaluated-options" tabindex="-1">2. Evaluated Options <a class="header-anchor" href="#_2-evaluated-options" aria-label="Permalink to &quot;2. Evaluated Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Option</th><th style="text-align:left;">Pros</th><th style="text-align:left;">Cons / Why Rejected or Selected</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Option A: PostgreSQL-Only</strong> (<code>JSONB</code> + <code>pgvector</code> + recursive CTEs)</td><td style="text-align:left;">Single backup/transaction boundary; native SQL joins everywhere</td><td style="text-align:left;">Heavy write amplification on chat/task section edits and survey responses; recursive CTE graph scoring (<code>PageRank</code> / <code>WCC</code>) degrades sharply on noisy social graphs; couples AI vector load to core billing CPU (<code>core</code> EC2 <code>640m</code> Postgres budget)</td></tr><tr><td style="text-align:left;"><strong>Option B: MongoDB-Only</strong> (Multi-document transactions for billing/RBAC)</td><td style="text-align:left;">Uniform document model across services</td><td style="text-align:left;">Lacks native relational FK cascades across the 97-table organizational/billing spine; awkward double-entry credit grant allocation (<code>credit_reservation_allocations</code>)</td></tr><tr><td style="text-align:left;"><strong>Option C: 5-Engine Polyglot Persistence with Strict Single-Service Ownership</strong> <em>(Selected)</em></td><td style="text-align:left;">Matches each workload to its purpose-built engine; isolates AI/graph memory from transactional billing</td><td style="text-align:left;">Requires application-level UUID joins, transactional outbox tables, and unified multi-engine backups (<code>db-backup</code>)</td></tr></tbody></table><hr><h2 id="_3-decision-architecture-ownership-matrix" tabindex="-1">3. Decision Architecture &amp; Ownership Matrix <a class="header-anchor" href="#_3-decision-architecture-ownership-matrix" aria-label="Permalink to &quot;3. Decision Architecture &amp; Ownership Matrix&quot;">​</a></h2><p>Every table, collection, or key namespace has <strong>exactly one owning service</strong> (<a href="./../architecture/service-boundaries.html">Service Boundaries</a>):</p><table tabindex="0"><thead><tr><th style="text-align:left;">Engine &amp; Version</th><th style="text-align:left;">Production Placement</th><th style="text-align:center;">Scale</th><th style="text-align:left;">Owning Service(s)</th><th style="text-align:left;">Assigned Domain Data</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>PostgreSQL 17</strong> (<code>postgres:17-alpine</code>)</td><td style="text-align:left;"><code>core</code> EC2 (<code>brandhub-postgres</code>)</td><td style="text-align:center;"><strong>97 tables</strong></td><td style="text-align:left;"><code>business-service</code> (<code>100%</code>)</td><td style="text-align:left;">Identity (<code>users</code>, <code>user_refresh_tokens</code>), <code>agencies</code> (<code>AGENCY</code> | <code>PERSONAL</code>), <code>workspaces</code>, <code>workspace_members</code>, <code>client_profiles</code>, <code>media_packages</code>, <code>media_campaigns</code>, 6-plan SePay billing (<code>billing_plan_versions</code>, <code>billing_plan_cycle_prices</code>, <code>billing_orders</code>, <code>transactions</code>), AI credit &amp; storage ledgers (<code>agency_credit_wallets</code>, <code>ai_credit_reservations</code>, <code>product_video_*</code>, <code>client_vault_*</code>), <code>engagement_reminders</code>, <code>user_notifications</code> (<code>LISTEN/NOTIFY</code>)</td></tr><tr><td style="text-align:left;"><strong>MongoDB 7.0</strong> (<code>mongo:7.0</code> local / <strong>Atlas</strong> prod)</td><td style="text-align:left;">Local Docker / MongoDB Atlas</td><td style="text-align:center;"><strong>52 collections</strong></td><td style="text-align:left;"><code>business-service</code> (<code>49</code>), <code>ai-service</code> (<code>2</code>), <code>publisher-service</code> (<code>1</code>)</td><td style="text-align:left;"><code>tasks</code>, <code>task_approvals</code>, <code>task_sections</code>, <code>posts</code>, <code>content_requests</code>, <code>materials</code>, <code>material_folders</code>, <code>material_versions</code>, <code>client_vault_shares</code>, <code>chat_*</code> (<code>8</code> collections), <code>video_*</code> (<code>4</code> collections), <code>surveys</code>, <code>mail_templates</code>, <code>social_accounts</code> (Facebook, Instagram, TikTok, Threads), <code>monitoring_*</code>, <code>knowledge_documents</code>, <code>ai_usage_logs</code>, <code>publish_logs</code></td></tr><tr><td style="text-align:left;"><strong>Redis 7.2</strong> (<code>redis:7.2-alpine</code>, AOF)</td><td style="text-align:left;"><code>core</code> EC2 (<code>172.31.24.149:6379</code>)</td><td style="text-align:center;">Key-Value / ZSET</td><td style="text-align:left;"><code>api-gateway</code>, <code>business-service</code>, <code>ai-service</code>, <code>publisher-service</code></td><td style="text-align:left;"><code>jwt:blacklist:{jti}</code>, <code>ratelimit:gateway:{userId}:{minute}</code>, <code>oauth:state:{state}</code>, <code>processingPostIds:{postId}:{platform}</code>, <code>trends:vn:{date}:{category}</code></td></tr><tr><td style="text-align:left;"><strong>ChromaDB 1.5.9</strong> (<code>chromadb/chroma:1.5.9</code>)</td><td style="text-align:left;"><code>core</code> EC2 (<code>172.31.24.149:8000</code>)</td><td style="text-align:center;"><code>384d</code> Cosine HNSW</td><td style="text-align:left;"><code>ai-service</code></td><td style="text-align:left;">Per-tenant Brand Knowledge collections (<code>client_{clientId}</code> / <code>brandhub_rag</code> filtered by <code>where={&quot;clientId&quot;: ...}</code>)</td></tr><tr><td style="text-align:left;"><strong>Neo4j 5.26</strong> (Community local / <strong>Aura</strong> prod)</td><td style="text-align:left;">Local add-on / Neo4j Aura</td><td style="text-align:center;">Property Graph</td><td style="text-align:left;"><code>ai-service</code></td><td style="text-align:left;"><code>:Trend</code>, <code>:CrawledPost</code>, <code>:KOL</code>, <code>:Brand</code>, <code>:Location</code>, <code>:Dish</code> nodes + APOC Entity Resolution</td></tr></tbody></table><hr><h2 id="_4-real-codebase-infrastructure-grounding" tabindex="-1">4. Real Codebase &amp; Infrastructure Grounding <a class="header-anchor" href="#_4-real-codebase-infrastructure-grounding" aria-label="Permalink to &quot;4. Real Codebase &amp; Infrastructure Grounding&quot;">​</a></h2><ul><li><strong>Bootstrap &amp; Migrations (<code>database/</code>)</strong>: <code>database/init/init-postgres-v2.sql</code> creates all 97 PostgreSQL tables (33 JPA <code>@Entity</code> classes + 64 SQL/JDBC tables in <code>brandhub-business-service</code>), while <code>database/init/init-mongo.js</code> creates all 52 MongoDB collections with <code>$jsonSchema</code> validators (29 <code>@Document</code> classes + 23 <code>MongoTemplate</code>/service stores). Incremental upgrades live in <code>database/migrations/{postgres,mongodb,neo4j}/</code>.</li><li><strong>Cross-Store Consistency Without 2PC</strong>: Cross-database workflows use durable outbox/tracking tables rather than distributed two-phase commits: <ul><li>Campaign approval (<code>FR 3.5.8</code>) records <code>campaign_deployments</code> in PostgreSQL and idempotently materializes <code>tasks</code> in MongoDB (guarded by unique index <code>uq_tasks_campaign_work_item</code>).</li><li>Material upload/purge writes <code>material_audit_outbox</code> in MongoDB and reconciles quota bytes into <code>agency_storage_usage</code> / <code>client_vault_storage_usage</code> via <code>material_audit_receipts</code> in PostgreSQL.</li></ul></li><li><strong>Unified Nightly Backups (<code>prod/hosts/core/db-backup/</code>)</strong>: A single FastAPI + APScheduler container on <code>core</code> EC2 dumps all 5 engines daily at <code>00:00 Asia/Ho_Chi_Minh</code> (<code>pg_dump -Fc</code>, <code>mongodump --archive --gzip</code>, <code>redis-cli --rdb</code>, ChromaDB <code>.tar.gz</code>, and Neo4j Bolt <code>.jsonl.gz</code>) into <code>s3://brandhub-db-backup-prd-134875421878</code> with 30-day lifecycle retention and point-in-time <code>POST /restore</code>.</li></ul><hr><h2 id="_5-trade-offs-operational-impact" tabindex="-1">5. Trade-offs &amp; Operational Impact <a class="header-anchor" href="#_5-trade-offs-operational-impact" aria-label="Permalink to &quot;5. Trade-offs &amp; Operational Impact&quot;">​</a></h2><h3 id="positive-outcomes" tabindex="-1">Positive Outcomes <a class="header-anchor" href="#positive-outcomes" aria-label="Permalink to &quot;Positive Outcomes&quot;">​</a></h3><ul><li><strong>Zero Financial Drift</strong>: PostgreSQL row locks, immutable <code>billing_guard_plan_version</code> triggers, and <code>ai_credit_reservations</code> guarantee exact SePay billing and credit accounting even when upstream AI/GPU calls fail.</li><li><strong>Schema Agility for Creative Tools</strong>: Adding specialist task sections (<code>DA-1274</code>), chat attachments, or Video Space auto-edits only extends MongoDB <code>$jsonSchema</code> validators without locking relational tables.</li><li><strong>Sub-20ms Trend Reads</strong>: Serving ranked trends from Redis backed by Neo4j Aura + ChromaDB keeps heavy NLP/graph workloads off the transactional database.</li></ul><h3 id="accepted-costs-mitigations" tabindex="-1">Accepted Costs &amp; Mitigations <a class="header-anchor" href="#accepted-costs-mitigations" aria-label="Permalink to &quot;Accepted Costs &amp; Mitigations&quot;">​</a></h3><ul><li><strong>Application-Layer Soft Joins</strong>: MongoDB documents reference PostgreSQL UUIDs (<code>workspaceId</code>, <code>campaignId</code>, <code>createdByClientProfileId</code>) without database-enforced foreign keys; enforced via mandatory repository-layer filters in <a href="./../database/redis-cache/database-access-rules.html">Database Access Rules</a>.</li><li><strong>Multi-Engine Operational Surface</strong>: Engineers manage SQL, <code>mongosh</code>, and Cypher migrations, mitigated by deterministic Docker init mounts (<code>docker/compose/shared/databases.yaml</code>) and automated S3 backup/restore (<code>db-backup</code>).</li></ul>',23)])])}const h=t(c,[["render",s]]);export{u as __pageData,h as default};
